class RateLimiter:
    def __init__(self, per_minute):
        self.capacity = per_minute
        self.tokens = per_minute
        self.ts = time.time()
    def acquire(self):
        now = time.time()
        self.tokens = min(self.capacity, self.tokens + (now-self.ts)*self.capacity/60)
        self.ts = now
        if self.tokens < 1:
            time.sleep((1-self.tokens)*60/self.capacity)
            self.tokens = 0
        else:
            self.tokens -= 1

